import org.junit.jupiter.api.Test;

public class TextNormaliser {

    @Test
    public void testNormaliseWhitespace() {
        String input = "   Hello, world!   ";
        String expected = "Hello, world!";
        assertEquals(expected, normaliseWhitespace(input));
    }

    @Test
    public void testNormaliseLeadingWhitespace() {
        String input = "  Hello,  world!   ";
        String expected = "Hello, world!";
        assertEquals(expected, normaliseWhitespace(input));
    }

    @Test
    public void testNormaliseTrailingWhitespace() {
        String input = "Hello   ,   world!";
        String expected = "Hello, world!";
        assertEquals(expected, normaliseWhitespace(input));
    }

    @Test
    public void testNormaliseMultipleSpaces() {
        String input = "   Hello  world! ";
        String expected = "Hello world!";
        assertEquals(expected, normaliseWhitespace(input));
    }

    @Test
    public void testNormaliseSingleSpace() {
        String input = "Hello   !";
        String expected = "Hello !";
        assertEquals(expected, normaliseWhitespace(input));
    }

    @Test
    public void testNormaliseEmptyString() {
        String input = "";
        String expected = "";
        assertEquals(expected, normaliseWhitespace(input));
    }

    private String normaliseWhitespace(String text) {
        int i = 0;
        StringBuilder sb = new StringBuilder();
        while (i < text.length()) {
            if (text.charAt(i).isspace()) {
                if (sb.length() > 0) {
                    sb.append(text.charAt(i));
                }
            } else {
                break;
            }
            ++i;
        }
        return sb.toString();
    }

}
